-- Microsoft Dynamics 365 F&O -> canonical GOODS_RECEIPT (D365). Generated by tools/build_silver_sql.py.
SELECT 'D365' AS SOURCE_SLOT, 'Microsoft Dynamics 365 F&O' AS SOURCE_SYSTEM, g.ORIGPURCHID || '-' || g.PURCHLINELINENUMBER AS GR_DOC, g.ORIGPURCHID AS PO_NUMBER, g.PURCHLINELINENUMBER::STRING AS PO_ITEM,
  'D365' AS PLANT, h.ORDERACCOUNT AS SUPPLIER_ID, g.ITEMID AS MATERIAL, g.DELIVERYDATE AS GR_DATE, g.QTY AS GR_QTY,
  g.QTY * l.PURCHPRICE AS GR_VALUE, l.CURRENCYCODE AS CURRENCY
FROM {{ source('src_d365', 'vendpackingsliptrans') }} g JOIN {{ source('src_d365', 'purchline') }} l ON l.PURCHID = g.ORIGPURCHID AND l.LINENUMBER = g.PURCHLINELINENUMBER
JOIN {{ source('src_d365', 'purchtable') }} h ON h.PURCHID = g.ORIGPURCHID
